package com.zeptopluse.service; import com.zeptopluse.dto.*; import com.zeptopluse.entity.*; import com.zeptopluse.exception.ResourceNotFoundException; import com.zeptopluse.mapper.AddressMapper; import com.zeptopluse.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List; @Service @RequiredArgsConstructor @Transactional(readOnly=true) public class AddressService { private final CustomerRepository customers; private final CustomerAddressRepository addresses; private final AddressMapper mapper; public List<AddressResponse> list(Long customerId){if(!customers.existsById(customerId))throw new ResourceNotFoundException("Customer not found: "+customerId);return addresses.findByCustomerIdOrderByDefaultAddressDescIdDesc(customerId).stream().map(mapper::toResponse).toList();} @Transactional public AddressResponse create(Long customerId,AddressRequest request){Customer c=customers.findById(customerId).orElseThrow(()->new ResourceNotFoundException("Customer not found: "+customerId));CustomerAddress a=new CustomerAddress();a.setCustomer(c);mapper.update(a,request);if(request.defaultAddress())clearDefault(customerId);return mapper.toResponse(addresses.save(a));} @Transactional public AddressResponse update(Long id,AddressRequest request){CustomerAddress a=addresses.findById(id).orElseThrow(()->new ResourceNotFoundException("Address not found: "+id));mapper.update(a,request);if(request.defaultAddress())clearDefaultExcept(a.getCustomer().getId(),id);return mapper.toResponse(a);} @Transactional public void delete(Long id){if(!addresses.existsById(id))throw new ResourceNotFoundException("Address not found: "+id);addresses.deleteById(id);} private void clearDefault(Long customerId){addresses.findByCustomerIdOrderByDefaultAddressDescIdDesc(customerId).forEach(a->a.setDefaultAddress(false));} private void clearDefaultExcept(Long customerId,Long id){addresses.findByCustomerIdOrderByDefaultAddressDescIdDesc(customerId).stream().filter(a->!a.getId().equals(id)).forEach(a->a.setDefaultAddress(false));} }